<?php
$pdo=db();$manage=in_array($user['role'],['Administrator','Head','Clerk'],true);$vehicles=[];$routes=[];$assignments=[];$students=[];$drivers=[];$routeLearners=[];$register=[];$children=[];$familyRoutes=[];$familyChecks=[];$routeId=filter_var($_GET['route_id']??null,FILTER_VALIDATE_INT);$date=(string)($_GET['date']??date('Y-m-d'));$trip=(string)($_GET['trip']??'Outbound');$d=DateTimeImmutable::createFromFormat('!Y-m-d',$date);$e=DateTimeImmutable::getLastErrors();if($d===false||$d->format('Y-m-d')!==$date||($e!==false&&($e['warning_count']||$e['error_count']))||$date>date('Y-m-d'))$date=date('Y-m-d');if(!in_array($trip,['Outbound','Return'],true))$trip='Outbound';
if($manage){$vehicles=$pdo->query("SELECT v.*,u.full_name AS driver_name FROM transport_vehicles v LEFT JOIN users u ON u.id=v.driver_user_id ORDER BY FIELD(v.status,'Active','Maintenance','Retired'),v.registration")->fetchAll();$routes=$pdo->query("SELECT r.*,v.registration,v.make_model,v.seat_capacity,v.status AS vehicle_status,v.roadworthy_until,v.insurance_until,u.full_name AS driver_name,COUNT(a.id) AS occupied FROM transport_routes r JOIN transport_vehicles v ON v.id=r.vehicle_id LEFT JOIN users u ON u.id=v.driver_user_id LEFT JOIN transport_assignments a ON a.route_id=r.id AND a.status='Active' AND a.starts_on<=CURDATE() AND (a.ends_on IS NULL OR a.ends_on>=CURDATE()) GROUP BY r.id ORDER BY r.active DESC,r.route_name")->fetchAll();$students=$pdo->query("SELECT id,admission_no,first_name,last_name,form_level,stream FROM students WHERE status='Active' ORDER BY last_name,first_name LIMIT 1500")->fetchAll();$drivers=$pdo->query("SELECT id,full_name,role FROM users WHERE active=1 AND role IN ('Administrator','Head','Teacher','Clerk') ORDER BY full_name")->fetchAll();$assignments=$pdo->query("SELECT a.*,s.admission_no,s.first_name,s.last_name,s.form_level,s.stream,r.route_name,v.registration FROM transport_assignments a JOIN students s ON s.id=a.student_id JOIN transport_routes r ON r.id=a.route_id JOIN transport_vehicles v ON v.id=r.vehicle_id ORDER BY (a.status='Active') DESC,a.starts_on DESC,a.id DESC LIMIT 300")->fetchAll();if(!$routeId&&$routes)$routeId=(int)$routes[0]['id'];if($routeId){$q=$pdo->prepare("SELECT a.id assignment_id,a.student_id,a.pickup_point,a.starts_on,a.ends_on,s.admission_no,s.first_name,s.last_name,s.form_level,s.stream FROM transport_assignments a JOIN students s ON s.id=a.student_id WHERE a.route_id=:route AND a.status IN ('Active','Completed') AND a.starts_on<=:start_date AND (a.ends_on IS NULL OR a.ends_on>=:end_date) ORDER BY s.last_name,s.first_name");$q->execute(['route'=>$routeId,'start_date'=>$date,'end_date'=>$date]);$routeLearners=$q->fetchAll();$q=$pdo->prepare('SELECT student_id,status,note FROM transport_register WHERE route_id=:route AND travel_date=:date AND trip=:trip');$q->execute(['route'=>$routeId,'date'=>$date,'trip'=>$trip]);foreach($q->fetchAll() as $row)$register[(int)$row['student_id']]=$row;}}
else{$q=$pdo->prepare("SELECT DISTINCT s.id,s.admission_no,s.first_name,s.last_name,s.form_level,s.stream FROM guardian_user_links l JOIN student_guardians g ON g.id=l.guardian_id AND g.consent_status='Granted' JOIN students s ON s.id=g.student_id WHERE l.user_id=:user ORDER BY s.last_name,s.first_name");$q->execute(['user'=>$user['id']]);$children=$q->fetchAll();if($children){$q=$pdo->prepare("SELECT DISTINCT a.id,a.student_id,a.pickup_point,a.starts_on,a.ends_on,r.route_name,r.route_details,r.departure_time,r.return_time,v.registration,v.make_model,u.full_name AS driver_name FROM transport_assignments a JOIN transport_routes r ON r.id=a.route_id JOIN transport_vehicles v ON v.id=r.vehicle_id LEFT JOIN users u ON u.id=v.driver_user_id JOIN guardian_user_links l ON l.user_id=? JOIN student_guardians g ON g.id=l.guardian_id AND g.student_id=a.student_id AND g.consent_status='Granted' WHERE a.status='Active' AND a.starts_on<=CURDATE() AND (a.ends_on IS NULL OR a.ends_on>=CURDATE()) ORDER BY a.student_id");$q->execute([(int)$user['id']]);$familyRoutes=$q->fetchAll();$q=$pdo->prepare("SELECT DISTINCT tr.student_id,tr.travel_date,tr.trip,tr.status,tr.note FROM transport_register tr JOIN guardian_user_links l ON l.user_id=? JOIN student_guardians g ON g.id=l.guardian_id AND g.student_id=tr.student_id AND g.consent_status='Granted' ORDER BY tr.travel_date DESC,tr.trip,tr.student_id LIMIT 50");$q->execute([(int)$user['id']]);$familyChecks=$q->fetchAll();}}
?>
<div class="page-heading"><div><div class="eyebrow"><?= $manage?'FLEET & STUDENT SAFETY':'FAMILY PORTAL' ?></div><h1>School transport</h1><p class="subheading"><?= $manage?'Manage vehicles, routes, student seats and daily trip registers.':'View route assignments and recent bus-register updates for your linked learners.' ?></p></div></div>
