<section class="stat-strip"><div><span>Vehicles</span><b><?= count($vehicles) ?></b></div><div><span>Active routes</span><b><?= count(array_filter($routes,static fn($r)=>(int)$r['active']===1&&$r['vehicle_status']==='Active')) ?></b></div><div><span>Current route assignments</span><b><?= count(array_filter($assignments,static fn($a)=>$a['status']==='Active'&&$a['starts_on']<=date('Y-m-d')&&(!$a['ends_on']||$a['ends_on']>=date('Y-m-d')))) ?></b></div><div><span>Active learners</span><b><?= number_format(count($students)) ?></b></div></section>
<div class="academic-two-col"><section class="panel settings-panel"><h2>Add / update a vehicle</h2><p>Vehicle status, seat capacity and inspection dates stay on the fleet record.</p><?php if($vehicles): ?><details><summary>Update an existing vehicle</summary><div class="table-scroll"><table class="data-table"><thead><tr><th>Registration</th><th>Vehicle</th><th>Seats</th><th>Status</th><th>Edit</th></tr></thead><tbody><?php foreach($vehicles as $v): ?><tr><td><?= h($v['registration']) ?></td><td><?= h($v['make_model']) ?></td><td><?= (int)$v['seat_capacity'] ?></td><td><?= h($v['status']) ?></td><td><details><summary>Edit</summary><form method="post" action="actions/transport_vehicle_save.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="vehicle_id" value="<?= (int)$v['id'] ?>"><label>Registration<input name="registration" value="<?= h($v['registration']) ?>" maxlength="24" required></label><label>Vehicle / model<input name="make_model" value="<?= h($v['make_model']) ?>" maxlength="100" required></label><label>Seat capacity<input type="number" name="seat_capacity" min="1" max="200" value="<?= (int)$v['seat_capacity'] ?>" required></label><label>Driver<select name="driver_user_id"><option value="">Unassigned</option><?php foreach($drivers as $driver): ?><option value="<?= (int)$driver['id'] ?>" <?= (int)$v['driver_user_id']===(int)$driver['id']?'selected':'' ?>><?= h($driver['full_name']) ?> · <?= h($driver['role']) ?></option><?php endforeach; ?></select></label><label>Roadworthy expiry<input type="date" name="roadworthy_until" value="<?= h($v['roadworthy_until']??'') ?>"></label><label>Insurance expiry<input type="date" name="insurance_until" value="<?= h($v['insurance_until']??'') ?>"></label><label>Status<select name="status"><?php foreach(['Active','Maintenance','Retired'] as $status): ?><option <?= $v['status']===$status?'selected':'' ?>><?= h($status) ?></option><?php endforeach; ?></select></label><button class="outline-button">Save vehicle</button></form></details></td></tr><?php endforeach; ?></tbody></table></div></details><?php endif; ?><form method="post" action="actions/transport_vehicle_save.php" class="compact-form"><?= csrf_field() ?><label>Registration<input name="registration" maxlength="24" required placeholder="ABC 1234"></label><label>Vehicle / model<input name="make_model" maxlength="100" required placeholder="Toyota Coaster"></label><label>Seat capacity<input type="number" name="seat_capacity" min="1" max="200" required></label><label>Driver<select name="driver_user_id"><option value="">Unassigned</option><?php foreach($drivers as $driver): ?><option value="<?= (int)$driver['id'] ?>"><?= h($driver['full_name']) ?> · <?= h($driver['role']) ?></option><?php endforeach; ?></select></label><label>Roadworthy expiry<input type="date" name="roadworthy_until"></label><label>Insurance expiry<input type="date" name="insurance_until"></label><label>Status<select name="status"><option>Active</option><option>Maintenance</option><option>Retired</option></select></label><button class="primary-button">Add vehicle</button></form></section>
<section class="panel settings-panel"><h2>Create a route</h2><p>A route uses one active vehicle. Student allocations are limited to the available seats.</p><form method="post" action="actions/transport_route_save.php" class="compact-form"><?= csrf_field() ?><label>Route name<input name="route_name" maxlength="120" required placeholder="Highfield route"></label><label>Vehicle<select name="vehicle_id" required><option value="">Select active vehicle</option><?php foreach($vehicles as $v): if($v['status']==='Active'): ?><option value="<?= (int)$v['id'] ?>"><?= h($v['registration'].' · '.$v['make_model'].' · '.$v['seat_capacity'].' seats') ?></option><?php endif; endforeach; ?></select></label><label>Outbound time<input type="time" name="departure_time"></label><label>Return time<input type="time" name="return_time"></label><label class="full-width">Route and stops<textarea name="route_details" rows="3" maxlength="2000" placeholder="List main stops in order"></textarea></label><button class="primary-button">Create route</button></form></section></div>
<section class="panel settings-panel"><h2>Assign a learner to a route</h2><form method="post" action="actions/transport_assignment_save.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="operation" value="assign"><label>Active learner<select name="student_id" required><option value="">Select learner</option><?php foreach($students as $s): ?><option value="<?= (int)$s['id'] ?>"><?= h($s['last_name'].', '.$s['first_name'].' · '.$s['admission_no'].' · Form '.$s['form_level'].($s['stream']?' '.$s['stream']:'')) ?></option><?php endforeach; ?></select></label><label>Route<select name="route_id" required><option value="">Select route</option><?php foreach($routes as $r): if($r['active']&&$r['vehicle_status']==='Active'): ?><option value="<?= (int)$r['id'] ?>"><?= h($r['route_name'].' · '.$r['registration'].' · '.$r['occupied'].'/'.$r['seat_capacity']) ?></option><?php endif; endforeach; ?></select></label><label>Pickup point<input name="pickup_point" maxlength="120" required placeholder="School gate / stop name"></label><label>Starts on<input type="date" name="starts_on" min="<?= h(date('Y-m-d')) ?>" value="<?= h(date('Y-m-d')) ?>" required></label><button class="primary-button">Assign route</button></form></section>
<section class="panel learners-panel"><div class="panel-heading"><div><h2>Route register</h2><p>Daily outbound and return check for allocated learners</p></div></div><form method="get" class="compact-form"><input type="hidden" name="page" value="transport"><label>Route<select name="route_id" required><?php foreach($routes as $r): ?><option value="<?= (int)$r['id'] ?>" <?= (int)$routeId===(int)$r['id']?'selected':'' ?>><?= h($r['route_name'].' · '.$r['registration']) ?></option><?php endforeach; ?></select></label><label>Date<input type="date" name="date" max="<?= h(date('Y-m-d')) ?>" value="<?= h($date) ?>" required></label><label>Trip<select name="trip"><option <?= $trip==='Outbound'?'selected':'' ?>>Outbound</option><option <?= $trip==='Return'?'selected':'' ?>>Return</option></select></label><button class="outline-button">Load register</button></form><?php if($routeId): ?><form method="post" action="actions/transport_register_save.php"><?= csrf_field() ?><input type="hidden" name="route_id" value="<?= (int)$routeId ?>"><input type="hidden" name="travel_date" value="<?= h($date) ?>"><input type="hidden" name="trip" value="<?= h($trip) ?>"><div class="table-scroll"><table class="data-table"><thead><tr><th>Learner</th><th>Pickup point</th><th>Status</th><th>Note</th></tr></thead><tbody><?php foreach($routeLearners as $s): $old=$register[(int)$s['student_id']]??null; ?><tr><td><?= h($s['first_name'].' '.$s['last_name']) ?><small class="muted-cell"><?= h($s['admission_no']) ?> · Form <?= (int)$s['form_level'] ?></small></td><td><?= h($s['pickup_point']) ?></td><td><select name="learners[<?= (int)$s['student_id'] ?>][status]"><option value="">Not recorded</option><?php foreach(['Boarded','Not On Bus','Authorized Alternative'] as $state): ?><option <?= ($old['status']??'')===$state?'selected':'' ?>><?= h($state) ?></option><?php endforeach; ?></select></td><td><input name="learners[<?= (int)$s['student_id'] ?>][note]" maxlength="255" value="<?= h($old['note']??'') ?>"></td></tr><?php endforeach; if(!$routeLearners): ?><tr><td colspan="4" class="empty-cell">No learner allocations are active for this route on the selected date.</td></tr><?php endif; ?></tbody></table></div><?php if($routeLearners): ?><div class="form-actions"><button class="primary-button">Save <?= h($trip) ?> register</button></div><?php endif; ?></form><?php endif; ?></section>
<section class="panel learners-panel"><div class="panel-heading"><div><h2>Vehicles and routes</h2><p>Operational status and route capacity checks</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Route</th><th>Vehicle</th><th>Driver</th><th>Seats</th><th>Times / stops</th><th>Status / edit</th></tr></thead><tbody><?php foreach($routes as $r): ?><tr><td><b><?= h($r['route_name']) ?></b></td><td><?= h($r['registration'].' · '.$r['make_model']) ?><small class="muted-cell"><?= h($r['vehicle_status']) ?></small></td><td><?= h($r['driver_name']?:'Unassigned') ?></td><td><?= (int)$r['occupied'] ?> / <?= (int)$r['seat_capacity'] ?></td><td><?= $r['departure_time']?h(substr($r['departure_time'],0,5)):'—' ?> / <?= $r['return_time']?h(substr($r['return_time'],0,5)):'—' ?><?php if($r['route_details']): ?><details><summary>Stops</summary><p><?= nl2br(h($r['route_details'])) ?></p></details><?php endif; ?></td><td><span class="status-pill <?= $r['active']?'':'inactive' ?>"><?= $r['active']?'Active':'Inactive' ?></span><details><summary>Edit route</summary><form method="post" action="actions/transport_route_save.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="route_id" value="<?= (int)$r['id'] ?>"><label>Name<input name="route_name" value="<?= h($r['route_name']) ?>" maxlength="120" required></label><label>Vehicle<select name="vehicle_id"><?php foreach($vehicles as $v): if($v['status']==='Active'): ?><option value="<?= (int)$v['id'] ?>" <?= (int)$r['vehicle_id']===(int)$v['id']?'selected':'' ?>><?= h($v['registration'].' · '.$v['seat_capacity'].' seats') ?></option><?php endif; endforeach; ?></select></label><label>Outbound time<input type="time" name="departure_time" value="<?= h($r['departure_time']?substr($r['departure_time'],0,5):'') ?>"></label><label>Return time<input type="time" name="return_time" value="<?= h($r['return_time']?substr($r['return_time'],0,5):'') ?>"></label><label class="full-width">Route details<textarea name="route_details" maxlength="2000" rows="3"><?= h($r['route_details']??'') ?></textarea></label><label><input type="checkbox" name="active" value="1" <?= $r['active']?'checked':'' ?>> Active</label><button class="outline-button">Save route</button></form></details></td></tr><?php endforeach; if(!$routes): ?><tr><td colspan="6" class="empty-cell">Add a vehicle and route to begin.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel learners-panel"><div class="panel-heading"><div><h2>Student transport assignments</h2><p>Latest 300 assignments and route changes</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Learner</th><th>Route / vehicle</th><th>Pickup</th><th>Dates</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($assignments as $a): $current=$a['status']==='Active'&&$a['starts_on']<=date('Y-m-d')&&(!$a['ends_on']||$a['ends_on']>=date('Y-m-d')); ?><tr><td><?= h($a['first_name'].' '.$a['last_name']) ?><small class="muted-cell"><?= h($a['admission_no']) ?> · Form <?= (int)$a['form_level'] ?></small></td><td><?= h($a['route_name']) ?><small class="muted-cell"><?= h($a['registration']) ?></small></td><td><?= h($a['pickup_point']) ?></td><td><?= h(date('d M Y',strtotime($a['starts_on']))) ?> – <?= $a['ends_on']?h(date('d M Y',strtotime($a['ends_on']))):'Current' ?></td><td><span class="status-pill"><?= $current?'Current':($a['status']==='Active'?'Scheduled':h($a['status'])) ?></span></td><td><?php if($current): ?><form method="post" action="actions/transport_assignment_save.php" class="compact-form" onsubmit="return confirm('End this transport assignment?')"><?= csrf_field() ?><input type="hidden" name="operation" value="end"><input type="hidden" name="assignment_id" value="<?= (int)$a['id'] ?>"><label>Ends on<input type="date" name="ends_on" min="<?= h(date('Y-m-d')) ?>" value="<?= h(date('Y-m-d')) ?>" required></label><button class="outline-button compact-button">End assignment</button></form><?php endif; ?></td></tr><?php endforeach; if(!$assignments): ?><tr><td colspan="6" class="empty-cell">No transport assignments recorded.</td></tr><?php endif; ?></tbody></table></div></section>
<?php else: ?><section class="panel learners-panel"><div class="panel-heading"><div><h2>Current transport arrangements</h2><p>Only information for learners linked through a consented guardian contact is shown.</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Learner</th><th>Route / stops</th><th>Pickup point</th><th>Vehicle</th><th>Driver</th><th>Times</th></tr></thead><tbody><?php foreach($children as $child): $rows=array_values(array_filter($familyRoutes,static fn($a)=>(int)$a['student_id']===(int)$child['id'])); if(!$rows): ?><tr><td><?= h($child['first_name'].' '.$child['last_name']) ?> · Form <?= (int)$child['form_level'] ?></td><td colspan="5">No current transport assignment recorded.</td></tr><?php else: foreach($rows as $a): ?><tr><td><?= h($child['first_name'].' '.$child['last_name']) ?> · Form <?= (int)$child['form_level'] ?></td><td><?= h($a['route_name']) ?><?php if($a['route_details']): ?><details><summary>Stops</summary><p><?= nl2br(h($a['route_details'])) ?></p></details><?php endif; ?></td><td><?= h($a['pickup_point']) ?></td><td><?= h($a['registration'].' · '.$a['make_model']) ?></td><td><?= h($a['driver_name']?:'Unassigned') ?></td><td><?= $a['departure_time']?h(substr($a['departure_time'],0,5)):'—' ?> / <?= $a['return_time']?h(substr($a['return_time'],0,5)):'—' ?></td></tr><?php endforeach; endif; endforeach; ?></tbody></table></div></section><section class="panel learners-panel"><div class="panel-heading"><div><h2>Recent trip register updates</h2><p>Outbound and return records entered by the school</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Date</th><th>Learner</th><th>Trip</th><th>Register status</th><th>Note</th></tr></thead><tbody><?php foreach($familyChecks as $check): $child=null;foreach($children as $c)if((int)$c['id']===(int)$check['student_id']){$child=$c;break;} ?><tr><td><?= h(date('d M Y',strtotime($check['travel_date']))) ?></td><td><?= h(($child['first_name']??'Learner').' '.($child['last_name']??'')) ?></td><td><?= h($check['trip']) ?></td><td><?= h($check['status']) ?></td><td><?= h($check['note']?:'—') ?></td></tr><?php endforeach; if(!$familyChecks): ?><tr><td colspan="5" class="empty-cell">No trip register updates yet.</td></tr><?php endif; ?></tbody></table></div></section><?php endif; ?>
